'use strict';
const $=id=>document.getElementById(id), board=$('board'), ctx=board.getContext('2d');
const defaults=[['INK','#282d35'],['WHITE','#fffaf0'],['PINK','#f0a5b5'],['BLUSH','#f9d4d5'],['ROSE','#c95874'],['CREAM','#f1d6ac'],['BROWN','#986c50'],['COCOA','#614638'],['LILAC','#b7a6d4'],['BLUE','#8aafca'],['SKY','#c1deeb'],['MINT','#aed3bc'],['LEAF','#568571'],['YELLOW','#f0ce73'],['ORANGE','#e59a6e'],['GRAY','#a4aaa8']].map(([code,hex])=>({code,hex}));
let state={version:1,width:32,height:32,palette:defaults.map(p=>({...p})),frames:[Array(1024).fill(null)],fps:6}, current=0, selected='PINK',tool='paint', zoom=20,history=[],future=[],drawing=false,last=null,timer=null,image=null,crop=null,cropStart=null;
var workspaceReady=false;
const clone=x=>JSON.parse(JSON.stringify(x));
function notice(t){$('status').textContent=t}function checkpoint(){stop();if(workspaceReady){floating=null;selection=null;}history.push(JSON.stringify({state,current,selected}));if(history.length>60)history.shift();future=[]}function recover(s){const v=JSON.parse(s);state=v.state;current=v.current;selected=v.selected;sync();render()}
function persist(){try{localStorage.setItem('bead-island-v1',JSON.stringify(state));if(workspaceReady)persistWorkspace();notice('已自动保存到此浏览器')}catch{notice('自动保存失败，请保存工程文件')}}
function sync(){$('width').value=state.width;$('height').value=state.height;$('fps').value=state.fps;const p=state.palette.find(p=>p.code===selected)||state.palette[0];selected=p.code;$('code').value=p.code;$('color').value=p.hex}
const colorOf=c=>state.palette.find(p=>p.code===c)?.hex||'#ff00ff';
function light(hex){const n=parseInt(hex.slice(1),16);return ((n>>16)*.299+((n>>8)&255)*.587+(n&255)*.114)>150}
function drawGrid(c,frame,size,labels=true,lines=true,axes=true){const w=state.width,h=state.height,o=axes?size:0;c.canvas.width=w*size+o*2;c.canvas.height=h*size+o*2;c.clearRect(0,0,c.canvas.width,c.canvas.height);if(axes){c.fillStyle='#f4f6ef';c.fillRect(0,0,c.canvas.width,c.canvas.height)}for(let y=0;y<h;y++)for(let x=0;x<w;x++){const code=frame[y*w+x],px=o+x*size,py=o+y*size;if(code){c.fillStyle=colorOf(code);c.fillRect(px,py,size,size)}else if(axes){c.fillStyle=(x+y)%2?'#fff':'#f5f5f0';c.fillRect(px,py,size,size)}if(labels&&code&&size>=18){c.fillStyle=light(colorOf(code))?'#25362f':'#fff';c.font=`${Math.max(7,Math.min(12,size*.27))}px sans-serif`;c.textAlign='center';c.textBaseline='middle';c.fillText(code,px+size/2,py+size/2,size-3)}}if(lines){for(let x=0;x<=w;x++){c.strokeStyle=x%5===0?'#748c7b88':'#78867533';c.lineWidth=x%5===0?1.3:.5;c.beginPath();c.moveTo(o+x*size,o);c.lineTo(o+x*size,o+h*size);c.stroke()}for(let y=0;y<=h;y++){c.strokeStyle=y%5===0?'#748c7b88':'#78867533';c.lineWidth=y%5===0?1.3:.5;c.beginPath();c.moveTo(o,o+y*size);c.lineTo(o+w*size,o+y*size);c.stroke()}}if(axes){c.font=`${Math.max(7,Math.min(11,size*.35))}px sans-serif`;c.textAlign='center';c.textBaseline='middle';c.fillStyle='#7c8b7e';for(let x=0;x<w;x++){c.fillText(x+1,o+(x+.5)*size,size/2);c.fillText(x+1,o+(x+.5)*size,o+h*size+size/2)}for(let y=0;y<h;y++){c.fillText(y+1,size/2,o+(y+.5)*size);c.fillText(y+1,o+w*size+size/2,o+(y+.5)*size)}}}
function render(){drawGrid(ctx,state.frames[current],zoom,$('codes').checked,$('grid').checked);if($('onion').checked&&current>0&&!timer){ctx.globalAlpha=.2;const prev=state.frames[current-1],frame=state.frames[current];prev.forEach((c,i)=>{if(c&&!frame[i]){ctx.fillStyle=colorOf(c);ctx.fillRect(zoom+(i%state.width)*zoom,zoom+Math.floor(i/state.width)*zoom,zoom,zoom)}});ctx.globalAlpha=1}$('zoomLabel').textContent=zoom+' px';$('frameTitle').textContent=`画布 / 第 ${current+1} 帧`;$('summary').textContent=`${state.width} × ${state.height} · ${state.frames.length} 帧`;renderPalette();renderFrames();renderCounts();$('undo').disabled=!history.length;$('redo').disabled=!future.length;if(workspaceReady){drawSelection();renderDocuments()}}
function renderPalette(){const box=$('palette');box.replaceChildren();const query=$('search').value.toLowerCase();state.palette.filter(p=>p.code.toLowerCase().includes(query)).forEach(p=>{const b=document.createElement('button');b.className='swatch'+(p.code===selected?' selected':'');const i=document.createElement('i');i.style.background=p.hex;b.append(i,document.createTextNode(p.code));b.onclick=()=>{selected=p.code;sync();renderPalette()};box.append(b)})}
function counts(){const m=new Map();state.frames[current].forEach(c=>{if(c)m.set(c,(m.get(c)||0)+1)});return [...m].sort((a,b)=>b[1]-a[1])}
function renderCounts(){const list=counts();$('counts').replaceChildren();$('replaceFrom').replaceChildren();let total=0;list.forEach(([code,n])=>{total+=n;const row=document.createElement('div');row.className='countrow';const i=document.createElement('i');i.style.background=colorOf(code);const a=document.createElement('span');a.textContent=code;const b=document.createElement('span');b.textContent=n+' 颗';row.append(i,a,b);$('counts').append(row);const opt=document.createElement('option');opt.value=code;opt.textContent=code;$('replaceFrom').append(opt)});$('total').textContent=total+' 颗'}
function renderFrames(){$('frames').replaceChildren();state.frames.forEach((f,i)=>{const b=document.createElement('button');b.className='frame'+(i===current?' active':'');const c=document.createElement('canvas');drawGrid(c.getContext('2d'),f,2,false,false,false);const s=document.createElement('span');s.textContent=String(i+1).padStart(2,'0');b.append(c,s);b.onclick=()=>{stop();current=i;render()};$('frames').append(b)})}
function point(e){const r=board.getBoundingClientRect();return [Math.floor((e.clientX-r.left)*board.width/r.width/zoom)-1,Math.floor((e.clientY-r.top)*board.height/r.height/zoom)-1]}
function valid(x,y){return x>=0&&y>=0&&x<state.width&&y<state.height}
function put(x,y,value){if(valid(x,y))state.frames[current][y*state.width+x]=value}
function flood(x,y,value){const f=state.frames[current],old=f[y*state.width+x];if(old===value)return;const queue=[y*state.width+x];f[queue[0]]=value;for(let k=0;k<queue.length;k++){const i=queue[k],xx=i%state.width,yy=Math.floor(i/state.width);for(const [nx,ny]of [[xx-1,yy],[xx+1,yy],[xx,yy-1],[xx,yy+1]]){const ni=ny*state.width+nx;if(valid(nx,ny)&&f[ni]===old){f[ni]=value;queue.push(ni)}}}}
function line(a,b,value){let [x,y]=a,[tx,ty]=b,dx=Math.abs(tx-x),dy=-Math.abs(ty-y),sx=x<tx?1:-1,sy=y<ty?1:-1,err=dx+dy;while(true){put(x,y,value);if(x===tx&&y===ty)break;const e=2*err;if(e>=dy){err+=dy;x+=sx}if(e<=dx){err+=dx;y+=sy}}}
board.oncontextmenu=e=>e.preventDefault();board.onpointerdown=e=>{const [x,y]=point(e);if(!valid(x,y))return;stop();if(tool==='pick'&&e.button!==2){const c=state.frames[current][y*state.width+x];if(c){selected=c;sync();renderPalette()}return}checkpoint();const value=e.button===2||tool==='erase'?null:selected;if(tool==='fill'&&e.button!==2){flood(x,y,value);render();persist();return}drawing=true;last=[x,y];board.setPointerCapture(e.pointerId);put(x,y,value);board.dataset.erase=value===null?'1':'0';render()};board.onpointermove=e=>{const p=point(e);$('position').textContent=valid(...p)?`列 ${p[0]+1} · 行 ${p[1]+1}`:'画布外';if(drawing&&valid(...p)){line(last,p,board.dataset.erase==='1'?null:selected);last=p;render()}};function endStroke(){if(drawing){drawing=false;last=null;persist()}}board.onpointerup=endStroke;board.onpointercancel=endStroke;
$('tools').onclick=e=>{const b=e.target.closest('[data-tool]');if(!b)return;tool=b.dataset.tool;document.querySelectorAll('[data-tool]').forEach(x=>x.classList.toggle('active',x===b))};$('undo').onclick=()=>{endStroke();stop();if(history.length){future.push(JSON.stringify({state,current,selected}));recover(history.pop());persist()}};$('redo').onclick=()=>{stop();if(future.length){history.push(JSON.stringify({state,current,selected}));recover(future.pop());persist()}};
function dims(a,b){const w=Number(a),h=Number(b);if(!Number.isInteger(w)||!Number.isInteger(h)||w<1||h<1||w>200||h>200)throw Error('宽高需要是 1–200 的整数');return [w,h]}
function guarded(fn){return ()=>{try{fn()}catch(e){alert(e.message)}}}
$('resize').onclick=guarded(()=>{const [w,h]=dims($('width').value,$('height').value);checkpoint();const old=state.width;state.frames=state.frames.map(f=>Array.from({length:w*h},(_,i)=>{const x=i%w,y=Math.floor(i/w);return x<old&&y<state.height?f[y*old+x]:null}));state.width=w;state.height=h;render();persist()});$('blank').onclick=guarded(()=>{const [w,h]=dims($('width').value,$('height').value);if(!confirm('新建会替换当前工程，可撤销。继续？'))return;checkpoint();state.width=w;state.height=h;state.frames=[Array(w*h).fill(null)];current=0;render();persist()});
$('addColor').onclick=guarded(()=>{const code=$('code').value.trim();if(!code)throw Error('请输入色号');checkpoint();const p=state.palette.find(p=>p.code===code);if(p)p.hex=$('color').value;else state.palette.push({code,hex:$('color').value});selected=code;render();persist()});$('replace').onclick=()=>{const from=$('replaceFrom').value;if(!from||from===selected)return;checkpoint();state.frames[current]=state.frames[current].map(c=>c===from?selected:c);render();persist()};$('search').oninput=renderPalette;['codes','grid','onion'].forEach(id=>$(id).onchange=render);
$('plus').onclick=()=>{zoom=Math.min(60,zoom+2);render()};$('minus').onclick=()=>{zoom=Math.max(4,zoom-2);render()};$('fit').onclick=()=>{zoom=Math.max(4,Math.min(40,Math.floor(Math.min(($('viewport').clientWidth-65)/(state.width+2),($('viewport').clientHeight-65)/(state.height+2)))));render()};
function stop(){if(timer){clearInterval(timer);timer=null;$('play').textContent='▶ 播放'}}$('play').onclick=()=>{if(timer){stop();render();return}$('play').textContent='❚❚ 暂停';timer=setInterval(()=>{current=(current+1)%state.frames.length;render()},1000/state.fps)};$('fps').onchange=()=>{stop();checkpoint();state.fps=Math.max(1,Math.min(30,Math.round(Number($('fps').value)||6)));sync();persist()};function addFrame(copy){if(state.frames.length>=100)return alert('最多 100 帧');checkpoint();state.frames.splice(current+1,0,copy?[...state.frames[current]]:Array(state.width*state.height).fill(null));current++;render();persist()}$('duplicate').onclick=()=>addFrame(true);$('newFrame').onclick=()=>addFrame(false);$('deleteFrame').onclick=()=>{if(state.frames.length===1)return;checkpoint();state.frames.splice(current,1);current=Math.min(current,state.frames.length-1);render();persist()};
function download(data,name,type){const url=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function choose(accept,fn){$('file').value='';$('file').accept=accept;$('file').onchange=()=>{const f=$('file').files[0];if(f)Promise.resolve(fn(f)).catch(e=>alert('导入失败：'+e.message))};$('file').click()}
function validateProject(v){if(!v||v.version!==1)throw Error('不支持的工程版本');dims(v.width,v.height);if(!Array.isArray(v.palette)||!v.palette.length||v.palette.length>1000)throw Error('色卡数量无效');const ids=new Set();for(const p of v.palette){if(typeof p.code!=='string'||!p.code.trim()||p.code.length>20||ids.has(p.code)||!/^#[0-9a-f]{6}$/i.test(p.hex))throw Error('色卡格式无效或色号重复');ids.add(p.code)}if(!Array.isArray(v.frames)||!v.frames.length||v.frames.length>100)throw Error('帧数无效');for(const f of v.frames){if(!Array.isArray(f)||f.length!==v.width*v.height||f.some(c=>c!==null&&!ids.has(c)))throw Error('帧数据或色号无效')}if(!Number.isInteger(v.fps)||v.fps<1||v.fps>30)throw Error('FPS 无效');return {version:1,width:v.width,height:v.height,palette:v.palette.map(p=>({code:p.code,hex:p.hex})),frames:v.frames,fps:v.fps}}
$('save').onclick=()=>download(JSON.stringify(state,null,2),'豆屿工程.bead.json','application/json');$('open').onclick=()=>choose('.json',async f=>{if(f.size>30000000)throw Error('文件超过 30MB');const s=validateProject(JSON.parse(await f.text()));checkpoint();state=s;current=0;selected=state.palette[0].code;sync();render();persist()});$('paletteExport').onclick=()=>download(JSON.stringify(state.palette,null,2),'palette.json','application/json');$('paletteImport').onclick=()=>choose('.json',async f=>{if(f.size>1000000)throw Error('色卡超过 1MB');const p=JSON.parse(await f.text());validateProject({version:1,width:1,height:1,palette:p,frames:[[null]],fps:6});if(!$('paletteOnly').checked&&new Set([...state.palette,...p].map(x=>x.code)).size>1000)throw Error('合并后色卡超过 1000 色');checkpoint();if($('paletteOnly').checked){const old=new Map(state.palette.map(c=>[c.code,c.hex]));state.palette=p.map(c=>({code:c.code,hex:c.hex}));const mapped=new Map([...old].map(([code,hex])=>[code,nearest(...rgb(hex))]));state.frames=state.frames.map(f=>f.map(c=>c===null?null:mapped.get(c)));selected=state.palette[0].code}else p.forEach(c=>{const existing=state.palette.find(x=>x.code===c.code);if(existing)existing.hex=c.hex;else state.palette.push(c)});sync();render();persist()});
function sourceDraw(){const c=$('source'),g=c.getContext('2d');g.clearRect(0,0,c.width,c.height);g.drawImage(image,0,0,c.width,c.height);if(crop){g.strokeStyle='#f05d75';g.lineWidth=2;g.setLineDash([5,4]);g.strokeRect(crop.x, crop.y,crop.w,crop.h);if($('importMode').value==='chart'){const w=Number($('iw').value),h=Number($('ih').value);if(w>=1&&w<=200&&h>=1&&h<=200){g.strokeStyle='#ec617c88';g.lineWidth=.6;for(let i=1;i<w;i++){g.beginPath();g.moveTo(crop.x+crop.w*i/w,crop.y);g.lineTo(crop.x+crop.w*i/w,crop.y+crop.h);g.stroke()}for(let i=1;i<h;i++){g.beginPath();g.moveTo(crop.x,crop.y+crop.h*i/h);g.lineTo(crop.x+crop.w,crop.y+crop.h*i/h);g.stroke()}}}g.setLineDash([])}}function sourcePoint(e){const r=$('source').getBoundingClientRect();return {x:Math.max(0,Math.min($('source').width,(e.clientX-r.left)*$('source').width/r.width)),y:Math.max(0,Math.min($('source').height,(e.clientY-r.top)*$('source').height/r.height))}}
$('source').onpointerdown=e=>{cropStart=sourcePoint(e);$('source').setPointerCapture(e.pointerId)};$('source').onpointermove=e=>{if(!cropStart)return;const p=sourcePoint(e);crop={x:Math.min(cropStart.x,p.x),y:Math.min(cropStart.y,p.y),w:Math.abs(p.x-cropStart.x),h:Math.abs(p.y-cropStart.y)};sourceDraw()};$('source').onpointerup=()=>{cropStart=null;if(crop&&(crop.w<3||crop.h<3))crop=null;sourceDraw();if($('importMode').value==='pixel')$('importMode').value='image';updateConversionPreview()};$('source').onpointercancel=()=>{cropStart=null};$('resetCrop').onclick=()=>{crop=null;sourceDraw();updateConversionPreview()};
async function loadImportImage(f){const url=URL.createObjectURL(f);const im=new Image();try{await new Promise((ok,no)=>{im.onload=ok;im.onerror=()=>no(Error('无法读取此图片'));im.src=url});if(im.width*im.height>64000000)throw Error('图片过大，请缩小到 6400 万像素以内');image=im;const ratio=Math.min(1,600/im.width,700/im.height);$('source').width=Math.max(1,Math.round(im.width*ratio));$('source').height=Math.max(1,Math.round(im.height*ratio));crop=null;$('conversionPreview').width=300;$('chartInfo').textContent='正在检查图纸范围。未自动定位时，请框选内部网格并选择对应模式。';sourceDraw();$('importDialog').showModal();if(!tryAutoChart()&&$('importMode').value==='pixel'){try{detectPixels()}catch(e){$('pixelInfo').textContent=e.message}}}finally{URL.revokeObjectURL(url)}}
$('import').onclick=()=>{importQueue=[];choose('image/*',loadImportImage)};$('cancelImport').onclick=()=>{$('importDialog').close();finishImport()};

function rgb(hex){return [parseInt(hex.slice(1,3),16),parseInt(hex.slice(3,5),16),parseInt(hex.slice(5,7),16)]}function nearest(r,g,b){let best=Infinity,code=state.palette[0].code;for(const p of state.palette){const v=rgb(p.hex),d=(r-v[0])**2*.3+(g-v[1])**2*.59+(b-v[2])**2*.11;if(d<best){best=d;code=p.code}}return code}
// Extract a dominant color from a chart cell: avoid grid edges and center text.
function sampleCell(data,stride,x,y,chart,size=24){
 const samples=[];
 for(let yy=4;yy<size-4;yy++)for(let xx=4;xx<size-4;xx++){
  if(chart&&yy>=9&&yy<=16)continue;
  const off=((y*size+yy)*stride+x*size+xx)*4;
  if(data[off+3]>127)samples.push([data[off],data[off+1],data[off+2]]);
 }
 if(samples.length<12)return null;
 if(!chart)return [0,1,2].map(i=>samples.map(v=>v[i]).sort((a,b)=>a-b)[Math.floor(samples.length/2)]);
 const bins=new Map();for(const p of samples){const key=p.map(v=>v>>4).join(',');if(!bins.has(key))bins.set(key,[]);bins.get(key).push(p)}
 const dominant=[...bins.values()].sort((a,b)=>b.length-a.length)[0];
 return [0,1,2].map(i=>Math.round(dominant.reduce((sum,p)=>sum+p[i],0)/dominant.length));
}
function distance(a,b){return .3*(a[0]-b[0])**2+.59*(a[1]-b[1])**2+.11*(a[2]-b[2])**2}
function extractColors(pixels,limit){
 const bins=new Map();for(const p of pixels){if(!p)continue;const k=p.map(v=>v>>3).join(',');let b=bins.get(k);if(!b){b={sum:[0,0,0],count:0};bins.set(k,b)}b.count++;p.forEach((v,i)=>b.sum[i]+=v)}
 const points=[...bins.values()].map(b=>({rgb:b.sum.map(v=>v/b.count),count:b.count})).sort((a,b)=>b.count-a.count);
 if(!points.length)return {palette:[{code:'C001',hex:'#ffffff'}],frame:pixels.map(()=>null)};
 const centers=[points[0].rgb.slice()];while(centers.length<Math.min(limit,points.length)){
  let best=null,score=-1;for(const p of points){const d=Math.min(...centers.map(c=>distance(p.rgb,c)));const s=d*Math.sqrt(p.count);if(s>score){score=s;best=p.rgb}}if(score<4)break;centers.push(best.slice());
 }
 for(let it=0;it<10;it++){const sums=centers.map(()=>({rgb:[0,0,0],n:0}));for(const p of points){let k=0,d=Infinity;centers.forEach((c,i)=>{const v=distance(p.rgb,c);if(v<d){d=v;k=i}});sums[k].n+=p.count;p.rgb.forEach((v,j)=>sums[k].rgb[j]+=v*p.count)}sums.forEach((s,i)=>{if(s.n)centers[i]=s.rgb.map(v=>Math.round(v/s.n))})}
 const palette=centers.map((c,i)=>({code:'C'+String(i+1).padStart(3,'0'),hex:'#'+c.map(v=>Math.round(v).toString(16).padStart(2,'0')).join('')}));
 const frame=pixels.map(p=>{if(!p)return null;let k=0,d=Infinity;centers.forEach((c,i)=>{const v=distance(p,c);if(v<d){d=v;k=i}});return palette[k].code});
 return {palette,frame};
}
$('convert').onclick=guarded(()=>{
 if($('importMode').value==='chart'){convertChart();return}
 if($('importMode').value==='pixel'){convertPixelArt();return}
 const [w,h]=dims($('iw').value,$('ih').value),src=$('source'),box=crop||{x:0,y:0,w:src.width,h:src.height};
 if(box.w<1||box.h<1)throw Error('请重新框选区域');
 const limit=Number($('colorLimit').value);if(!Number.isInteger(limit)||limit<2||limit>256)throw Error('颜色上限需要是 2–256 的整数');
 const sx=image.width/src.width,sy=image.height/src.height,c=document.createElement('canvas'),chart=$('importMode').value==='chart';c.width=w*24;c.height=h*24;
 const g=c.getContext('2d',{willReadFrequently:true});g.imageSmoothingEnabled=!chart;
 let dx=0,dy=0,dw=c.width,dh=c.height;
 if(!chart&&$('keepAspect').checked){const ratio=Math.min(dw/(box.w*sx),dh/(box.h*sy));dw=box.w*sx*ratio;dh=box.h*sy*ratio;dx=(c.width-dw)/2;dy=(c.height-dh)/2}
 g.drawImage(image,box.x*sx,box.y*sy,box.w*sx,box.h*sy,dx,dy,dw,dh);
 const data=g.getImageData(0,0,c.width,c.height).data,pixels=[],threshold=255-Number($('tolerance').value);
 for(let y=0;y<h;y++)for(let x=0;x<w;x++){let p=sampleCell(data,c.width,x,y,chart);if(p&&$('removeWhite').checked&&p.every(v=>v>=threshold))p=null;pixels.push(p)}
 const extracted=$('colorMode').value!=='palette',result=extracted?extractColors(pixels,limit):{frame:pixels.map(p=>p?nearest(...p):null)};
 if(!confirm('转换会替换当前工程（可撤销），继续？'))return;
 checkpoint();if(extracted){state.palette=result.palette;selected=state.palette[0].code}state.width=w;state.height=h;state.frames=[result.frame];current=0;sync();render();persist();$('importDialog').close();finishImport();
 notice(extracted?'已提取原图颜色；C 编号是临时色号，可手动修改':'已匹配当前色卡，颜色可能与原图不同');
});
